problems.solutionCode:
function createCircuitBreaker(asyncOperation, options = {}) {
  const failureThreshold = options.failureThreshold !== undefined ? options.failureThreshold : 3;
  const resetTimeoutMs = options.resetTimeoutMs !== undefined ? options.resetTimeoutMs : 50;

  let state = 'CLOSED';
  let failureCount = 0;
  let openedAt = 0;

  return {
    async execute(...args) {
      const now = Date.now();

      if (state === 'OPEN') {
        if (now - openedAt >= resetTimeoutMs) {
          state = 'HALF_OPEN';
        } else {
          throw new Error('CIRCUIT_BREAKER_OPEN');
        }
      }

      try {
        const result = await asyncOperation(...args);
        if (state === 'HALF_OPEN' || state === 'CLOSED') {
          state = 'CLOSED';
          failureCount = 0;
        }
        return result;
      } catch (err) {
        failureCount++;
        if (state === 'HALF_OPEN' || failureCount >= failureThreshold) {
          state = 'OPEN';
          openedAt = Date.now();
        }
        throw err;
      }
    },
    getState() {
      if (state === 'OPEN' && Date.now() - openedAt >= resetTimeoutMs) {
        return 'HALF_OPEN';
      }
      return state;
    }
  };
}

module.exports = { createCircuitBreaker };

visibleTests.testCode:
let failures = 0;
const flakyClearingHouse = async () => {
  failures++;
  throw new Error('Clearing house gateway error');
};

const breaker = createCircuitBreaker(flakyClearingHouse, { failureThreshold: 3, resetTimeoutMs: 40 });

for (let i = 0; i < 3; i++) {
  await assert.rejects(async () => breaker.execute(), /Clearing house gateway error/);
}

assert.strictEqual(breaker.getState(), 'OPEN');
await assert.rejects(async () => breaker.execute(), /CIRCUIT_BREAKER_OPEN/);
assert.strictEqual(failures, 3);

let healthy = false;
const remoteService = async () => {
  if (!healthy) throw new Error('Outage');
  return 'SETTLED_TX_OK';
};

const breaker = createCircuitBreaker(remoteService, { failureThreshold: 2, resetTimeoutMs: 30 });
await assert.rejects(async () => breaker.execute(), /Outage/);
await assert.rejects(async () => breaker.execute(), /Outage/);
assert.strictEqual(breaker.getState(), 'OPEN');

await new Promise(r => setTimeout(r, 40));
assert.strictEqual(breaker.getState(), 'HALF_OPEN');

healthy = true;
const probeResult = await breaker.execute();
assert.strictEqual(probeResult, 'SETTLED_TX_OK');
assert.strictEqual(breaker.getState(), 'CLOSED');

